#!/usr/bin/env bash
# RunX Player — remove the last user-visible "Max Player" / "MaxPlayer"
# strings (trademark follow-up: E Galactic e.U., EUTM 019160905 / 019160201).
#
# The app was renamed to RunX Player in +87, but these places still showed the
# old brand to users and to every server the app talks to. A reviewer or the
# complainant can screenshot any of them, so they are scrubbed here.
#
# 5 files, 10 strings:
#   lib/utils/network_headers.dart      User-Agent  MaxPlayer/1.0 -> RunXPlayer/1.0
#                                       (dropped "like MX Player" too - MX Player
#                                       is a third-party brand)
#   lib/screens/player_screen_impl.dart screenshot name maxplayer_* -> runx_*,
#                                       album Pictures/MaxPlayer -> Pictures/RunX,
#                                       gallery toast updated
#   lib/screens/cloud_storage_screen.dart
#                                       error text + fallback path Videos|Movies/
#                                       MaxPlayer -> .../RunX
#   lib/widgets/user_manual_sheet.dart  manual text Pictures/MaxPlayer -> /RunX
#   MainActivity.kt (native)            MediaStore "Movies|Music/MaxPlayer" and the
#                                       legacy "Movies/Max Player" folder + its
#                                       returned location string -> RunX, and two
#                                       hard-coded User-Agent strings
#
# NOT touched on purpose: package id com.hypertechlabs.maxplayer, the
# maxplayer/* MethodChannels, notification channel ids and the push topics.
# Nothing installed on a user's device breaks - only new saves use the new
# album names.
#
# Usage — run from your existing repository root:
#   bash update_android_brand_scrub.sh --check
#   bash update_android_brand_scrub.sh
#   bash update_android_brand_scrub.sh --verify
#
# Then:
#   flutter analyze --no-fatal-infos && flutter test
#   git add -A && git commit -m "Brand scrub: no user-visible MaxPlayer strings"
#   git push origin main
set -euo pipefail
command -v python3 >/dev/null || { echo 'Python 3 is required'; exit 1; }
python3 - "$@" <<'ANDBRAND_PY'
import base64, gzip, hashlib, json, pathlib, subprocess, sys

