d4wl/aJk9mBzbZfV22E/F+CclJqKYcfWie+ikvt//j+TdhasMMAFAA=="""


def fail(m):
    print('STOP: ' + m, file=sys.stderr)
    sys.exit(1)


def digest(d):
    return hashlib.sha256(d).hexdigest()


args = sys.argv[1:] or ['--apply']
if len(args) != 1 or args[0] not in ['--check', '--apply', '--verify']:
    fail('Use no argument (apply), --check, --apply or --verify from the repository root.')
mode = args[0]

blob = ''.join(PAYLOAD.split())
if hashlib.sha256(blob.encode()).hexdigest() != PAYLOAD_HASH:
    fail('Payload is corrupted (checksum mismatch). Re-download the script.')
entries = json.loads(gzip.decompress(base64.b64decode(blob)))

try:
    root = pathlib.Path(subprocess.check_output(
        ['git', 'rev-parse', '--show-toplevel'], stderr=subprocess.DEVNULL
    ).decode().strip()).resolve()
except Exception:
    fail('Not inside a Git repository.')
if pathlib.Path.cwd().resolve() != root:
    fail('Run from your existing repository root; no files changed.')
if 'name: maxplayer' not in (root / 'pubspec.yaml').read_text(encoding='utf-8'):
    fail('pubspec.yaml for maxplayer not found in this repository.')

if mode == '--verify':
    bad = [e['path'] for e in entries
           if (digest((root / e['path']).read_bytes()) if (root / e['path']).is_file() else None) != e['after']]
    if bad:
        fail('Not in the scrubbed state:\n  ' + '\n  '.join(bad))
    print('VERIFIED: all %d file hashes match.' % len(entries))
    sys.exit(0)

todo, problems = [], []
for e in entries:
    p = root / e['path']
    if not p.is_file():
        problems.append('  missing: ' + e['path'])
        continue
    actual = digest(p.read_bytes())
    if actual == e['after']:
        continue
    if actual != e['before']:
        problems.append('  %s is neither the expected original nor already scrubbed' % e['path'])
        continue
    todo.append(e)
if problems:
    fail('These files are unexpected:\n' + '\n'.join(problems))

print('Brand scrub: %d file(s) need changes.' % len(todo))
if mode == '--check':
    for e in todo:
        print('  scrub   ' + e['path'])
    print('CHECK PASSED. No files written.')
    sys.exit(0)

for e in todo:
    (root / e['path']).write_bytes(base64.b64decode(e['data']))
    print('  scrubbed ' + e['path'])
print('')
print('Next: flutter analyze --no-fatal-infos && flutter test')
print('      git add -A && git commit -m "Brand scrub: no user-visible MaxPlayer strings"')
ANDBRAND_PY
